function parseNested(qs) {
  const result = {};
  qs.split('&').forEach((pair) => {
    const [rawKey, value] = pair.split('=');
    const keys = rawKey.replace(/\]/g, '').split('[');
    let node = result;
    keys.forEach((k, i) => {
      if (i === keys.length - 1) node[k] = decodeURIComponent(value);
      else node = node[k] = node[k] || {};
    });
  });
  return result;
}

